INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 25, 'theory', 'Квиз: эксплуатация oVirt');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 25, 0, 'Каков правильный порядок обновления установки oVirt?', '["Хосты, затем менеджер, затем версия центра данных", "Версия кластера, менеджер, хосты", "Копия, менеджер, хосты по одному, версии кластера и центра данных", "Менеджер и все хосты одновременно, копия потом"]', 2, 'Сначала копия и обновление менеджера, потом хосты по одному через maintenance, и лишь затем версия совместимости: кластер, потом центр данных.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 25, 1, 'Машина не запустилась, а менеджер показал ошибку команды. С чего разумнее начать поиск причины?', '["Взять идентификатор корреляции из engine.log и найти его в vdsm.log выбранного хоста, затем в журналах libvirt и QEMU", "Сразу переустановить хост", "Перезагрузить менеджер и посмотреть, пройдёт ли ошибка", "Отключить SELinux на всех хостах"]', 0, 'Идём по цепочке слоёв: менеджер, VDSM, libvirt, QEMU. Идентификатор корреляции связывает строки команды в разных журналах и показывает первую ошибку.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 25, 2, 'Чем чаще всего вызвано состояние хоста NonOperational?', '["Хост отключили для обслуживания", "У хоста пропало сердцебиение", "Менеджер обновляют до новой версии", "Хосту не хватает требуемой логической сети или он не видит домен хранилища"]', 3, 'Связь с хостом есть, но он не соответствует требованиям кластера: нет сети или хранилища. Потеря связи даёт NonResponsive, а обслуживание даёт Maintenance.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 25, 3, 'Что означает запас ёмкости N+1 для кластера?', '["В кластере всегда на один хост меньше, чем нужно", "После отказа самого большого хоста оставшиеся должны вместить все машины", "Памяти должно быть на одну виртуальную машину больше", "К каждому хосту нужен отдельный запасной менеджер"]', 1, 'N+1 означает, что потеря самого большого хоста не лишает машины места: суммарная ёмкость без него не меньше нагрузки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 25, 4, 'Каков статус oVirt по состоянию на 2026 год?', '["Закрыт, выпуски прекращены", "Развивается Red Hat, поддержка вендора входит в подписку", "Проект сообщества, последний выпуск 4.5.7 в январе 2026, Red Hat отошла к OpenShift Virtualization", "Полностью переписан на Kubernetes"]', 2, 'Проект живёт силами сообщества: выпуск 4.5.7 вышел в январе 2026 года, а Red Hat сосредоточилась на OpenShift Virtualization.');
